WITH monthly AS (
  SELECT customer_id, strftime('%Y-%m', payment_date) AS ym, SUM(amount) AS val
  FROM payment GROUP BY customer_id, ym
), d AS (
  SELECT customer_id, (val - LAG(val) OVER (PARTITION BY customer_id ORDER BY ym)) AS chg
  FROM monthly
), a AS (
  SELECT customer_id, AVG(chg) AS metric FROM d WHERE chg IS NOT NULL GROUP BY customer_id
)
SELECT c.first_name || ' ' || c.last_name AS full_name
FROM a JOIN customer c ON c.customer_id = a.customer_id
ORDER BY a.metric DESC LIMIT 1;

WITH monthly AS (
  SELECT customer_id, strftime('%Y-%m', payment_date) AS ym, SUM(amount) AS val
  FROM payment GROUP BY customer_id, ym
), d AS (
  SELECT customer_id, ym, val, LAG(val) OVER (PARTITION BY customer_id ORDER BY ym) AS prev
  FROM monthly
), a AS (
  SELECT customer_id, AVG((val - prev) * 1.0 / prev) AS metric
  FROM d WHERE prev IS NOT NULL AND prev <> 0 GROUP BY customer_id
)
SELECT c.first_name || ' ' || c.last_name AS full_name
FROM a JOIN customer c ON c.customer_id = a.customer_id
ORDER BY a.metric DESC LIMIT 1;

WITH monthly AS (
  SELECT customer_id, strftime('%Y-%m', payment_date) AS ym, SUM(amount) AS val
  FROM payment GROUP BY customer_id, ym
), d AS (
  SELECT customer_id, ym, val - LAG(val) OVER (PARTITION BY customer_id ORDER BY ym) AS chg FROM monthly
), a AS (
  SELECT customer_id, AVG(chg) AS metric, COUNT(*) AS n_changes FROM d WHERE chg IS NOT NULL GROUP BY customer_id
)
SELECT c.customer_id, c.first_name || ' ' || c.last_name AS full_name, ROUND(a.metric,2) AS avg_monthly_change, a.n_changes
FROM a JOIN customer c ON c.customer_id = a.customer_id
ORDER BY a.metric DESC LIMIT 8;

SELECT customer_id, strftime('%Y-%m', payment_date) AS ym, COUNT(*) AS n_pay, ROUND(SUM(amount),2) AS total
FROM payment WHERE customer_id IN (487,445,163,160,15)
GROUP BY customer_id, ym ORDER BY customer_id, ym;

